// TASK-0033 — Progressive Topographic UX, product acceptance in real WebView2.
// No simulated DOM, no alternate renderer, no personal data: the tree under
// test was generated by task0033-seed-proof.py and dies with the proof root.
import assert from "node:assert/strict";
import { writeFile, readFile } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
assert(/^task0033-[a-f0-9]+$/.test(variant));

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, absolutePath, entriesWritten } = seed;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? r.exceptionDetails.text);
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const invoke = (command, args = {}) =>
  evaluate(`window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`);
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
/** A real, trusted mouse click, dispatched by the input pipeline — never `element.click()`. */
async function clickSelector(selector) {
  const rect = await evaluate(
    `(()=>{const el=document.querySelector(${JSON.stringify(selector)}); if(!el) return null; const r=el.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2,w:r.width,h:r.height};})()`,
  );
  assert(rect, `clickSelector: not found or not laid out — ${selector}`);
  assert(rect.w > 0 && rect.h > 0, `clickSelector: zero-size target — ${selector}`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: rect.x, y: rect.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: rect.x, y: rect.y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: rect.x, y: rect.y, button: "left", clickCount: 1 });
  await pause(150);
  return rect;
}
async function worldTransform() {
  const raw = await evaluate(
    `document.querySelector('[data-testid="composed-world"]')?.getAttribute('transform') ?? ''`,
  );
  const m = /translate\(([-\d.]+)\s+([-\d.]+)\)\s*scale\(([-\d.]+)\)/.exec(raw);
  assert(m, `unparsable world transform: ${raw}`);
  return { tx: Number(m[1]), ty: Number(m[2]), scale: Number(m[3]) };
}
/**
 * Emulates a viewport of exactly `width` x `height`, regardless of the real
 * WebView2 window's own size. `Emulation.setDeviceMetricsOverride` resizes
 * the actual rendering surface — layout, `getBoundingClientRect` and
 * `Page.captureScreenshot` all honour it — unlike `Browser.setWindowBounds`,
 * which a WebView2 page-scoped CDP session need not implement at all.
 */
async function resizeWindow(width, height) {
  await send("Emulation.setDeviceMetricsOverride", {
    width,
    height,
    deviceScaleFactor: 0,
    mobile: false,
  });
  await pause(400);
  const measured = await evaluate("({width: window.innerWidth, height: window.innerHeight})");
  return measured;
}
const jargon = ["view_budget_or_focus", "outside_current_projection", "omitted_direct_children", "enfants directs hors vue"];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal jargon "${word}" leaked into ${where}`);
}
const escaped = absolutePath.split("\\").join("\\\\");
function assertNoPathLeak(text, where) {
  assert(!text.includes(absolutePath) && !text.includes(escaped), `absolute path leaked into ${where}`);
}
function byPath(view, relativePath) {
  const node = view.nodes.find((n) => n.relativePath === relativePath);
  assert(node, `node missing from projection: ${relativePath}`);
  return node;
}
function domCounts() {
  return evaluate(
    `(()=>{const t=document.querySelector('.map-territory[data-brain-id=${JSON.stringify(brainId)}]');return {treeitems:t.querySelectorAll('[role="treeitem"]').length,aggregates:t.querySelectorAll('[data-aggregate]').length,directories:t.querySelectorAll('[data-node-kind="directory"]').length,files:t.querySelectorAll('[data-node-kind="file"]').length};})()`,
  );
}

const results = { task: "TASK-0033", passes: {} };

// --- 1. index the large synthetic REAL_ROOT tree, by a real keystroke -------
await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
await activate('[data-testid="lifecycle-refresh"]');
await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled && document.querySelectorAll('[role="treeitem"]').length > 0`);
const build = await invoke("map_refresh", { brainId });
assert.equal(build.sourceKind, "REAL_ROOT");
assert.equal(build.sourceRead, true);
assert(build.nodeCount >= 5000, `indexed corpus too small: ${build.nodeCount}`);
assert.equal(build.nodeCount, entriesWritten + 1, "root included, scanner count matches the seed exactly");
results.indexedNodeCount = build.nodeCount;

// --- 2. root projection: bounded, ordinary target respected ------------------
const root = await invoke("map_view", { brainId });
assert(root.materializedCount <= 64, `ordinary root projection exceeds 64: ${root.materializedCount}`);
assert(root.materializedCount + root.aggregates.length <= root.viewBudget, "total exceeds VIEW_BUDGET");
assert(root.nodeCount > root.materializedCount, "this tree must be bigger than the ordinary target");
const nodeA = byPath(root, "A");
const nodeB = byPath(root, "B");
const nodeC = byPath(root, "C");
const nodeD = byPath(root, "D");

// --- 3. pure-directory overflow (A): all shown children are directories -----
const viewA = await invoke("map_view", { brainId, focusId: nodeA.id });
assert(viewA.materializedCount <= 64);
const aChildren = viewA.nodes.filter((n) => n.parentId === nodeA.id);
assert(aChildren.every((n) => n.kind === "directory"), "A must show only directories");
assert.equal(aChildren.length, 62, "A's page size");
const aAgg = viewA.aggregates.find((a) => a.parentId === nodeA.id);
assert(aAgg, "A must carry a continuation aggregate");
assert.equal(aAgg.omittedDirectChildren, 120 - aChildren.length);

// --- 4. mixed overflow (B): every directory wins before a single file -------
const viewB = await invoke("map_view", { brainId, focusId: nodeB.id });
const bChildren = viewB.nodes.filter((n) => n.parentId === nodeB.id);
const bDirs = bChildren.filter((n) => n.kind === "directory");
const bFiles = bChildren.filter((n) => n.kind === "file");
assert.equal(bDirs.length, 40, "all 40 directories must be retained under B");
assert(bFiles.length > 0 && bFiles.length < 90, "some but not all files admitted under B");
assert.equal(bDirs.length + bFiles.length, bChildren.length);
const bAgg = viewB.aggregates.find((a) => a.parentId === nodeB.id);
assert(bAgg);
assert.equal(bAgg.omittedDirectChildren, 130 - bChildren.length);

// --- 5. flat pile (C): files fill the target, and continuation has no accumulation
const viewC1 = await invoke("map_view", { brainId, focusId: nodeC.id });
const c1Children = viewC1.nodes.filter((n) => n.parentId === nodeC.id);
assert(c1Children.every((n) => n.kind === "file"));
assert.equal(c1Children.length, 62);
const cAgg1 = viewC1.aggregates.find((a) => a.parentId === nodeC.id);
assert(cAgg1 && cAgg1.nextCursor, "C must offer a continuation cursor");
const viewC2 = await invoke("map_view", { brainId, focusId: nodeC.id, after: cAgg1.nextCursor });
const c2Children = viewC2.nodes.filter((n) => n.parentId === nodeC.id);
const overlap = c1Children.filter((n1) => c2Children.some((n2) => n2.id === n1.id));
assert.equal(overlap.length, 0, "continuation must not repeat the first page — no accumulation, no omission collision");
assert(c2Children.length <= 62, "continuation must respect the same ordinary target, not grow unbounded");

// --- 6. deep ancestry (D): several real levels of branch navigation ---------
let focusId = nodeD.id;
for (let level = 1; level <= 5; level++) {
  const view = await invoke("map_view", { brainId, focusId });
  const child = view.nodes.find((n) => n.parentId === focusId && n.kind === "directory");
  assert(child, `D must have a directory child at hop ${level}`);
  focusId = child.id;
}
const deepView = await invoke("map_view", { brainId, focusId });
assert(deepView.nodes.some((n) => n.id === focusId), "deep focus must be materialised");

// --- 7. no internal jargon, no absolute path, anywhere visible --------------
for (const view of [root, viewA, viewB, viewC1, viewC2, deepView]) {
  const text = JSON.stringify(view);
  assertNoPathLeak(text, "map_view payload");
}

// --- 8. per-resolution product replay ----------------------------------------

async function clickButtonWithText(text) {
  const found = await evaluate(
    `(()=>{const b=[...document.querySelectorAll('button')].find(x=>x.textContent.trim()===${JSON.stringify(text)});if(!b) return false; b.focus(); return true;})()`,
  );
  assert(found, `button not found: ${text}`);
  await key("Enter");
}

async function replayResolution(width, height) {
  const label = `${width}x${height}`;
  const measured = await resizeWindow(width, height);
  assert(Math.abs(measured.width - width) <= 4 && Math.abs(measured.height - height) <= 4, `viewport did not resize to ${label}: got ${measured.width}x${measured.height}`);

  await invoke("map_open", { brainId });

  // Start from a known state: the root, at whatever scale the app currently
  // holds (a readable one, from the first opening or a prior pass' reset).
  await clickButtonWithText("Revenir à la racine");
  // `B-mixte` is a root-level sibling of `A`: it is only materialised while
  // root itself is the focus, never while viewing inside `A`'s own branch —
  // exactly the transition this click must produce.
  await until(`!!document.getElementById(${JSON.stringify(`${brainId}-map-node-${nodeB.id}`)})`);
  const scaleAtRoot = (await worldTransform()).scale;

  // Select A's card with a real mouse click, then enter the branch explicitly.
  await clickSelector(`#${brainId}-map-node-${nodeA.id}`);
  await until(`document.querySelector('.details__name')?.textContent?.trim() === ${JSON.stringify("A")}`);
  await clickButtonWithText("Explorer la sélection");
  const firstChildOfA = aChildren[0].id;
  await until(`!!document.getElementById(${JSON.stringify(`${brainId}-map-node-${firstChildOfA}`)})`);
  const scaleAfterBranch = (await worldTransform()).scale;
  assert(
    Math.abs(scaleAfterBranch - scaleAtRoot) < 1e-6,
    `branch navigation must not change scale: ${scaleAtRoot} -> ${scaleAfterBranch}`,
  );
  // The details panel refetches on every projection change and shows a
  // loading/empty state while that request is in flight; wait for it to
  // settle back on `A` rather than sampling it mid-fetch.
  await until(`document.querySelector('.details__name')?.textContent?.trim() === ${JSON.stringify("A")}`);
  const focusedName = await evaluate(`document.querySelector('.details__name')?.textContent?.trim()`);
  assert.equal(focusedName, "A", "details panel must stay coherent with the new focus");
  const focusedPath = await evaluate(`document.querySelector('.details__path')?.textContent?.trim()`);
  assertNoPathLeak(focusedPath ?? "", "details panel path");

  // A's page stacks 62 directories in one column — tall enough that an
  // exhaustive fit must shrink well below a readable scale. This is exactly
  // the shape `Ajuster`/`Réinitialiser` must tell apart.
  await activate('[data-testid="fit-composition"]');
  const afterFit = await worldTransform();
  assert(afterFit.scale < scaleAfterBranch * 0.9, "Ajuster must actually shrink this tall column to fit it");

  // `Ajuster` moved focus to its own button; the zoom keys are handled by the
  // canvas itself, so it must be refocused before they mean anything.
  await evaluate(`document.querySelector('[data-testid="composed-canvas"]').focus()`);
  // Each "+" multiplies the scale by ~1.35; from a fit as small as ~0.065
  // (this tall a column), a handful of presses is not enough to clear the
  // readable scale of 1 — 16 comfortably does, whatever the fit started at.
  for (let i = 0; i < 16; i++) await key("+");
  const zoomedIn = await worldTransform();
  assert(zoomedIn.scale > afterFit.scale - 1e-9, "zoom keys must zoom in");

  await activate('[data-testid="reset-view"]');
  const afterReset = await worldTransform();
  assert(afterReset.scale < zoomedIn.scale, "Réinitialiser must leave the zoomed-in state");
  // Réinitialiser must land back on the readable scale it started this branch
  // at, never on the exhaustive-fit shrink `Ajuster` just produced.
  assert(
    afterReset.scale > afterFit.scale * 1.5,
    `Réinitialiser (${afterReset.scale}) looks like an exhaustive fit (${afterFit.scale}), not a readable scale`,
  );

  // A pastille is small and carries the product vocabulary, never a card-sized block.
  const pill = await evaluate(
    `(()=>{const r=document.querySelector('.map-territory [data-aggregate] rect.map-aggregate__pill'); if(!r) return null; return {w:Number(r.getAttribute('width')),h:Number(r.getAttribute('height')),text:r.closest('[data-aggregate]').textContent};})()`,
  );
  assert(pill, "no aggregate pill rendered under the current branch");
  assert(pill.w < 160 && pill.h < 40, `pill too large: ${pill.w}x${pill.h}`);
  assertNoJargon(pill.text, "aggregate pill text");
  assert(pill.text.includes("Voir la suite"), "aggregate pill must carry the product CTA");

  const bodyText = await evaluate("document.body.textContent");
  assertNoJargon(bodyText, "page body text");
  assertNoPathLeak(bodyText, "page body text");

  const dom = await domCounts();
  const currentView = await invoke("map_view", { brainId, focusId: nodeA.id });
  assert.equal(dom.treeitems, currentView.materializedCount, "DOM node count must match the product projection");
  assert.equal(dom.aggregates, currentView.aggregates.length);

  const screenshot = await send("Page.captureScreenshot", { format: "png" });
  await writeFile(`.filetopo-sandbox/${variant}/topographic-${width}x${height}.png`, Buffer.from(screenshot.data, "base64"));

  return {
    label,
    measuredViewport: measured,
    fitScale: afterFit.scale,
    zoomedInScale: zoomedIn.scale,
    resetScale: afterReset.scale,
    resetIsNotExhaustiveFit: afterReset.scale > afterFit.scale * 1.5,
    branchNavigationPreservedScale: true,
    aggregatePill: { width: pill.w, height: pill.h },
    domMatchesProjection: true,
  };
}

results.passes["1366x768"] = await replayResolution(1366, 768);
results.passes["1920x1080"] = await replayResolution(1920, 1080);

// --- 9. host log / artefact-level path leak check ----------------------------
const hostLog = await readFile(join(".filetopo-sandbox", variant, "app.log"), "utf8").catch(() => "");
assertNoPathLeak(hostLog, "host log");
assertNoJargon(hostLog, "host log");

assert.equal(fatal.length, 0, "fatal page/console errors");

const host = await invoke("map_host_info");
const artifact = {
  ...results,
  status: "NONCANONICAL_ENGINEERING_EVIDENCE",
  engine: "Windows Tauri / real WebView2",
  webviewVersion: host.webviewVersion,
  tauriVersion: host.tauriVersion,
  sqliteVersion: host.sqliteVersion,
  source: "REAL_ROOT registered internally (task0033-seed-proof.py) -> explicit map_refresh -> bounded map_view -> MapApp/MapView",
  tree: {
    generatedByTheProofNotByTheUser: true,
    personalDataUsed: false,
    indexedNodeCount: build.nodeCount,
    branches: {
      "A": { directDirectories: 120 },
      "B": { directDirectories: 40, directFiles: 90 },
      "C": { directFiles: cAgg1.omittedDirectChildren + c1Children.length },
      "D": { depth: 15 },
    },
  },
  projection: {
    ordinaryTargetRespected: root.materializedCount <= 64,
    directoryFirstOnPureOverflow: { shown: 62, allDirectories: true, omitted: aAgg.omittedDirectChildren },
    directoryFirstOnMixedOverflow: { directoriesShown: bDirs.length, filesShown: bFiles.length, omitted: bAgg.omittedDirectChildren },
    continuationNoAccumulation: overlap.length === 0,
    deepAncestryNavigable: true,
  },
  fatalConsoleErrors: fatal.length,
  absolutePathLeak: false,
  internalJargonLeak: false,
  limits: [
    "No personal brain: the analysed tree was generated by task0033-seed-proof.py and dies with the proof root",
    "The REAL_ROOT row is written by the seed, as TASK-0032 §7 established; this pass measures the product path after internal registration",
    "Development workstation; not a modest-laptop acceptance test",
    "Window resize uses CDP Emulation.setDeviceMetricsOverride rather than a physical monitor change",
  ],
};
await writeFile("docs/performance/runs/TASK-0033-webview2.json", JSON.stringify(artifact, null, 2) + "\n");
console.log(JSON.stringify(artifact));
ws.close();
